{
  "Comment": "Run managed gene-edit candidate batch ranking",
  "StartAt": "RunBatchRanking",
  "States": {
    "RunBatchRanking": {
      "Type": "Task",
      "Resource": "arn:aws:states:::sagemaker:createProcessingJob.sync",
      "Parameters": {
        "ProcessingJobName.$": "$.processing_job_name",
        "RoleArn": "arn:aws:iam::975050327570:role/AmazonSageMakerExecutionRole-GeneEditRanking",
        "AppSpecification": {
          "ImageUri": "975050327570.dkr.ecr.us-east-1.amazonaws.com/gene-edit-ranking-batch@sha256:c4dcf6747a7ebf94d07bda46c00e89741f0ca0e2b6b004349a4153e438a15285",
          "ContainerArguments.$": "States.Array('--input-s3-uri', $.input_s3_uri, '--scoring-date', $.scoring_date)"
        },
        "ProcessingResources": {
          "ClusterConfig": {
            "InstanceCount": 1,
            "InstanceType": "ml.m5.large",
            "VolumeSizeInGB": 10
          }
        },
        "StoppingCondition": {
          "MaxRuntimeInSeconds": 1800
        }
      },
      "ResultPath": "$.processing_result",
      "Retry": [
        {
          "ErrorEquals": [
            "SageMaker.AmazonSageMakerException",
            "SageMaker.ResourceLimitExceededException",
            "States.Timeout"
          ],
          "IntervalSeconds": 30,
          "MaxAttempts": 2,
          "BackoffRate": 2
        }
      ],
      "Catch": [
        {
          "ErrorEquals": [
            "States.ALL"
          ],
          "ResultPath": "$.error",
          "Next": "BatchRankingFailed"
        }
      ],
      "Next": "BatchRankingSucceeded"
    },
    "BatchRankingSucceeded": {
      "Type": "Pass",
      "Result": {
        "status": "SUCCEEDED"
      },
      "ResultPath": "$.workflow_status",
      "End": true
    },
    "BatchRankingFailed": {
      "Type": "Fail",
      "Error": "BatchRankingFailed",
      "Cause": "The SageMaker batch-ranking processing job failed."
    }
  }
}
